/**
 * Structured template document content - the single source of truth shared by
 * the .docx/.pdf generator (scripts/generate-templates.mjs) and the in-browser
 * preview. The JSON is regenerated by `npm run generate:templates`.
 */
import rawDocuments from "./template-documents.json";

export type DocControlSection = { type: "doccontrol"; rows: [string, string][] };
export type MetaSection = { type: "meta"; text: string };
export type HeadingSection = { type: "heading"; text: string };
export type SubheadingSection = { type: "subheading"; text: string };
export type ParaSection = { type: "para"; text: string };
export type ClauseSection = { type: "clause"; num: string; text: string };
export type BulletsSection = { type: "bullets"; items: string[] };
export type TableSection = { type: "table"; headers: string[]; rows: string[][] };
export type DividerSection = { type: "divider" };

export type DocSection =
  | DocControlSection
  | MetaSection
  | HeadingSection
  | SubheadingSection
  | ParaSection
  | ClauseSection
  | BulletsSection
  | TableSection
  | DividerSection;

export type TemplateDocument = {
  title: string;
  sections: DocSection[];
};

export const TEMPLATE_DOCUMENTS = rawDocuments as unknown as Record<
  string,
  TemplateDocument
>;

export function getTemplateDocument(slug: string): TemplateDocument | null {
  return TEMPLATE_DOCUMENTS[slug] ?? null;
}

/** Top-level numbered headings - used to build the "What's inside" outline. */
export function getDocHeadings(doc: TemplateDocument): string[] {
  return doc.sections
    .filter((s): s is HeadingSection => s.type === "heading")
    .map((s) => s.text);
}

/** The document-control key/value rows (reference, version, classification…). */
export function getDocControl(doc: TemplateDocument): [string, string][] {
  const dc = doc.sections.find(
    (s): s is DocControlSection => s.type === "doccontrol"
  );
  return dc?.rows ?? [];
}

/** Approximate reading length used for "N-minute read" / page-count hints. */
export function getDocWordCount(doc: TemplateDocument): number {
  let words = 0;
  const count = (t: string) => (t.trim() ? t.trim().split(/\s+/).length : 0);
  for (const s of doc.sections) {
    switch (s.type) {
      case "meta":
      case "heading":
      case "subheading":
      case "para":
        words += count(s.text);
        break;
      case "clause":
        words += count(s.num) + count(s.text);
        break;
      case "bullets":
        words += s.items.reduce((n, i) => n + count(i), 0);
        break;
      case "table":
        words += s.headers.reduce((n, h) => n + count(h), 0);
        words += s.rows.reduce(
          (n, row) => n + row.reduce((m, c) => m + count(c), 0),
          0
        );
        break;
      case "doccontrol":
        words += s.rows.reduce((n, [k, v]) => n + count(k) + count(v), 0);
        break;
    }
  }
  return words;
}
